import ast,hashlib,json; from pathlib import Path; r=Path('/workspace'); result={};
for p in sorted(r.glob('*.py')):
 tree=ast.parse(p.read_text()); result[p.name]={'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'functions':[n.name for n in tree.body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))],'classes':[n.name for n in tree.body if isinstance(n,ast.ClassDef)]}
Path('/output/source-index.json').write_text(json.dumps(result,indent=2)+'\n')
